    all_nodes = set(data['durations'].keys())
    if not all_nodes:
        return {'duration': 0, 'path': []}

    memo = {}

    def get_best_path(node):
        if node in memo:
            return memo[node]

        # Если у узла нет предшественников, лучший путь - сам узел
        if not data['deps'].get(node, []):
            memo[node] = (data['durations'][node], [node])
            return memo[node]

        # Ищем лучший путь среди всех предшественников
        best_result = None

        for parent in data['deps'][node]:
            parent_cost, parent_path = get_best_path(parent)
            current_cost = parent_cost + data['durations'][node]
            current_path = parent_path + [node]

            if best_result is None:
                best_result = (current_cost, current_path)
            else:
                # Сравниваем: сначала по длине (убывание), потом лексикографически (возрастание)
                if (current_cost, current_path) > best_result:
                    best_result = (current_cost, current_path)

        memo[node] = best_result
        return best_result

    # Вычисляем лучший путь для всех узлов
    results = {}
    for node in all_nodes:
        results[node] = get_best_path(node)

    # Находим глобальный максимум среди всех узлов
    global_best = None
    for node, (cost, path) in results.items():
        if global_best is None:
            global_best = (cost, path)
        else:
            if (cost, path) > global_best:
                global_best = (cost, path)

    return {'duration': global_best[0], 'path': global_best[1]}
